        events.push({ kind: 'text', text: `${playerMon.name} recovered ${healed} HP!` })
      }
      const enemyMove = chooseEnemyMove(state, rng)
      performMove(state, 'enemy', enemyMove, events, rng)
      burnTick(state, events)
      checkFaints(state, events)
      return events
    }

