/* party */
.party-list { display: grid; gap: 9px; }
.party-card {
  display: grid; grid-template-columns: 64px 1fr auto; gap: 11px; align-items: center;
  background: var(--paper); border: 2px solid var(--ink); border-radius: 12px;
  padding: 8px 10px; box-shadow: 0 3px 0 rgba(36, 21, 15, .18);
}
.party-card.fainted { filter: grayscale(.55); opacity: .75; }
.party-card.selected { outline: 3px solid var(--sun); outline-offset: 2px; }
.party-sprite { width: 64px; height: 64px; border-radius: 10px; background: radial-gradient(circle at 50% 60%, #fff3cf, #f0c877); border: 2px solid var(--ink); }
.party-sprite canvas { width: 100%; height: 100%; image-rendering: pixelated; }
.party-info { min-width: 0; }
.party-info .line1 { display: flex; align-items: center; gap: 7px; flex-wrap: wrap; }
.party-info strong { font-size: 15px; }
.party-hp { display: flex; align-items: center; gap: 6px; margin-top: 4px; }
.party-hp .hp-track { height: 8px; max-width: 190px; }
.party-hp span { font-family: var(--mono); font-size: 10px; color: var(--ink-faint); }
.party-moves { display: flex; flex-wrap: wrap; gap: 3px; margin-top: 5px; }
.party-moves span { font-size: 9px; font-weight: 700; background: rgba(36, 21, 15, .07); border-radius: 5px; padding: 1px 5px; }
.party-side { text-align: right; display: flex; flex-direction: column; gap: 4px; align-items: flex-end; }
.party-stats { font-family: var(--mono); font-size: 9px; color: var(--ink-faint); line-height: 1.35; }

/* dex */
.dex-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; }
.dex-card {
  position: relative; background: var(--paper); border: 2px solid var(--ink); border-radius: 10px;
  padding: 6px; text-align: center; box-shadow: 0 3px 0 rgba(36, 21, 15, .16);
}
.dex-card.locked { background: #ece2cc; }
.dex-card canvas { width: 100%; height: auto; aspect-ratio: 1; image-rendering: pixelated; }
.dex-card.locked canvas { filter: brightness(0) opacity(.35); }
.dex-card .dex-no { position: absolute; top: 4px; left: 6px; font-family: var(--mono); font-size: 8px; color: var(--ink-faint); }
.dex-card .dex-name { font-size: 11px; font-weight: 900; margin-top: 1px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.dex-card .dex-state { font-size: 8px; font-weight: 800; text-transform: uppercase; letter-spacing: .08em; color: var(--ink-faint); }
.dex-card.caught { border-color: #3c7a2a; box-shadow: 0 3px 0 rgba(60, 122, 42, .3); }
.dex-card.caught .dex-state { color: #3c7a2a; }
.dex-filters { display: flex; gap: 6px; margin-bottom: 10px; flex-wrap: wrap; }

/* bag / shop */
.item-list { display: grid; gap: 7px; }
.item-row {
  display: flex; align-items: center; gap: 10px;
  background: var(--paper); border: 2px solid var(--ink); border-radius: 10px; padding: 8px 10px;
  box-shadow: 0 2px 0 rgba(36, 21, 15, .15);
}
.item-icon {
  width: 34px; height: 34px; border-radius: 50%; flex: 0 0 auto;
  border: 2px solid var(--ink); position: relative; background: #f0d9a0;
}
.item-icon.ball { background: linear-gradient(180deg, #b5763b 0 44%, #2a1b14 44% 54%, #f6e8c8 54% 100%); }
.item-icon.gold { background: linear-gradient(180deg, #ffdd66 0 44%, #8a6410 44% 54%, #fff3bd 54% 100%); }
.item-icon.potion { background: linear-gradient(180deg, #cfe8d8 0 30%, #6fc4cf 30% 100%); }
.item-icon.super { background: linear-gradient(180deg, #ffd7a3 0 30%, #e8573c 30% 100%); }
.item-icon.mango { background: radial-gradient(circle at 40% 35%, #ffe066, #e8573c); }
.item-info { min-width: 0; flex: 1; }
.item-info strong { font-size: 13px; }
.item-info p { font-size: 10px; color: var(--ink-faint); font-weight: 600; line-height: 1.35; }
.item-count { font-family: var(--mono); font-size: 13px; font-weight: 700; min-width: 28px; text-align: right; }
.item-buy { display: flex; align-items: center; gap: 8px; }
.item-price { font-family: var(--mono); font-size: 11px; font-weight: 700; color: var(--ink-soft); }

/* quest/help */
.quest-steps { display: grid; gap: 8px; }
.quest-step { display: flex; gap: 10px; align-items: flex-start; padding: 9px 10px; background: var(--paper); border: 2px solid var(--ink); border-radius: 10px; }
.quest-step .qs-mark { width: 22px; height: 22px; border-radius: 50%; border: 2px solid var(--ink); background: #ddd0b8; display: grid; place-items: center; font-size: 12px; font-weight: 900; flex: 0 0 auto; }
.quest-step.done .qs-mark { background: var(--lime); }
.quest-step strong { font-size: 13px; display: block; }
.quest-step p { font-size: 11px; color: var(--ink-soft); font-weight: 600; }
.help-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.help-card { background: var(--paper); border: 2px solid var(--ink); border-radius: 10px; padding: 10px; }
.help-card h4 { font-size: 12px; letter-spacing: .09em; text-transform: uppercase; margin-bottom: 4px; }
.help-card p, .help-card li { font-size: 11px; line-height: 1.5; color: var(--ink-soft); font-weight: 600; }
.help-card kbd { font-size: 9px; }
.help-card ul { margin: 0; padding-left: 16px; }
.toggle-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 8px 0; border-top: 1px dashed rgba(36, 21, 15, .2); }
.toggle-row:first-child { border-top: 0; }

/* ending */
.ending-card {
  background:
    radial-gradient(circle at 50% 0%, rgba(255, 224, 138, .5), transparent 55%),
    linear-gradient(180deg, #0c5c62 0%, #073b45 60%, #062a31 100%);
  color: var(--cream);
  text-align: center;
  border-color: #1b120c;
  overflow: hidden;
}
.ending-card::before {
  content: ""; position: absolute; inset: -40% -20% auto; height: 90%;
  background: conic-gradient(from 180deg at 50% 0%, rgba(255, 230, 150, .14) 0 8deg, transparent 8deg 24deg);
  animation: spinSlow 30s linear infinite; pointer-events: none;
}
.ending-card h2 { font-size: clamp(34px, 6vw, 64px); color: #ffe36b; -webkit-text-stroke: 2px var(--ink); paint-order: stroke fill; text-shadow: 0 4px 0 #8a3520; }
.ending-card .eyebrow { color: #ffcf98; }
.ending-card .lede { color: #e8f3df; }
.ending-sprite { width: 160px; height: 160px; margin: 6px auto 0; }
.ending-sprite canvas { width: 100%; height: 100%; image-rendering: pixelated; }
.ending-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; margin: 16px 0; }
.ending-stat { background: rgba(255, 255, 255, .08); border: 1px solid rgba(255, 246, 223, .25); border-radius: 10px; padding: 8px 6px; }
.ending-stat strong { display: block; font-family: var(--mono); font-size: 18px; color: #ffe36b; }
.ending-stat span { font-size: 9px; text-transform: uppercase; letter-spacing: .09em; opacity: .8; }
.confetti { position: absolute; inset: 0; pointer-events: none; overflow: hidden; }
.confetti i { position: absolute; width: 7px; height: 11px; top: -20px; opacity: .9; animation: confettiFall linear infinite; }

/* confirm */
.confirm-card { width: min(460px, 100%); text-align: center; }
.confirm-card h2 { font-size: 26px; }
.confirm-card p { font-size: 13px; line-height: 1.5; font-weight: 600; color: var(--ink-soft); margin: 8px 0 16px; }

/* misc */
.empty-note { padding: 14px; text-align: center; font-size: 12px; font-weight: 700; color: var(--ink-faint); background: var(--paper); border: 2px dashed rgba(36, 21, 15, .25); border-radius: 10px; }
.money-line { display: flex; justify-content: flex-end; align-items: center; gap: 6px; font-family: var(--mono); font-size: 12px; font-weight: 700; margin-bottom: 8px; }
.transition { position: absolute; inset: 0; background: #fffdf2; z-index: 20; pointer-events: none; opacity: 0; transition: opacity .25s ease; }
.transition.show { opacity: 1; }
.flash { position: fixed; inset: 0; background: #fffdf2; z-index: 40; pointer-events: none; opacity: 0; }
.flash.show { animation: flashOut .6s ease both; }

/* ============================================================ ANIMATIONS */
@keyframes dropIn { from { opacity: 0; transform: translateY(-18px) scale(.97); } to { opacity: 1; transform: none; } }
@keyframes riseIn { from { opacity: 0; transform: translateY(18px); } to { opacity: 1; transform: none; } }
@keyframes popIn { from { opacity: 0; transform: scale(.94) translateY(8px); } to { opacity: 1; transform: none; } }
@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
@keyframes dialogueIn { from { opacity: 0; transform: translate(-50%, 14px); } to { opacity: 1; transform: translate(-50%, 0); } }
@keyframes toastIn { from { opacity: 0; transform: translate(-50%, -10px) scale(.96); } to { opacity: 1; transform: translate(-50%, 0) scale(1); } }
@keyframes bob { 0%, 100% { transform: translate(-50%, 0); } 50% { transform: translate(-50%, -4px); } }
@keyframes sway { 0%, 100% { transform: rotate(18deg); } 50% { transform: rotate(26deg); } }
@keyframes hitFlash { 0% { opacity: 0; } 30% { opacity: .85; } 100% { opacity: 0; } }
@keyframes flashOut { 0% { opacity: 1; } 100% { opacity: 0; } }
@keyframes shake { 0%, 100% { transform: translateX(0); } 20% { transform: translateX(-6px); } 40% { transform: translateX(5px); } 60% { transform: translateX(-4px); } 80% { transform: translateX(3px); } }
@keyframes spinSlow { to { transform: rotate(360deg); } }
@keyframes confettiFall { to { transform: translateY(110vh) rotate(720deg); } }
@keyframes ballToss {
  0% { transform: translate(0, 0) scale(.8); }
  45% { transform: translate(120px, -70px) scale(1); }
  100% { transform: translate(250px, -30px) scale(.9); }
}
@keyframes ballShake { 0%, 100% { transform: rotate(0); } 25% { transform: rotate(-18deg); } 75% { transform: rotate(18deg); } }
