async function blackout() {
  mode = 'transition'
  flashScreen()
  YD.audio.sfx('faint')
  await wait(420)
  engine.healParty(state.party)
  state.leadIndex = 0
  const lost = Math.min(state.coins, 100)
  state.coins -= lost
  setPlayer(world.spawn.x, world.spawn.y, 'down')
  updateHud()
  updateArea(false)
  mode = 'world'
  await showDialogue([{
    name: 'Nurse Orchid', role: 'Health Hut', portrait: 'nurse',
