  player.px = tx * world.TILE + world.TILE / 2
  player.py = ty * world.TILE + world.TILE
  player.dir = dir || 'down'
  player.moving = false
  player.t = 0
  player.frame = 0
  camera.x = player.px
  camera.y = player.py - 8
  state.position = { x: tx, y: ty, dir: player.dir }
}

