  const zone = world.zoneAt(player.tx, player.ty)
  if (zone === state.zone) return
  state.zone = zone
  $('area-name').textContent = ZONE_NAMES[zone] || 'Sweetwater Bay'
  if (announce) {
    YD.audio.sfx('toast')
