const path = require('path')
const root = '/home/runner/work/PlayGround/PlayGround'
const data = require(path.join(root, 'js/data.js'))
const engine = require(path.join(root, 'js/engine.js'))
const map = require(path.join(root, 'js/map.js'))

const scenario = process.argv[2] || 'fern'
const world = map.createWorld()

const party = ['pimenta', 'turtide', 'ackee', 'anancy', 'cockpit', 'seacow'].map(id => engine.makeMonster(id, 45))
for (const mon of party) {
  // Keep every partner alive at full strength so battle flow is easy to verify.
  mon.hp = mon.maxHp
  mon.fainted = false
}

const positions = {
  fern: { x: 9, y: 25, dir: 'up' },
  finn: { x: 53, y: 40, dir: 'up' },
  zeph: { x: 33, y: 16, dir: 'up' },
  drbird: { x: 38, y: 5, dir: 'up' },
  shop: { x: 36, y: 27, dir: 'up' },
  heal: { x: 42, y: 31, dir: 'up' },
  town: { x: 33, y: 34, dir: 'down' }
}

const badges = {
  fern: { fern: false, finn: false, zeph: false },
  finn: { fern: true, finn: false, zeph: false },
  zeph: { fern: true, finn: true, zeph: false },
  drbird: { fern: true, finn: true, zeph: true }
}[scenario] || { fern: false, finn: false, zeph: false }

const defeated = {
  fern: {},
  finn: { fern: true },
  zeph: { fern: true, finn: true },
  drbird: { fern: true, finn: true, zeph: true }
}[scenario] || {}

const pos = positions[scenario] || positions.town
if (!world.walkable(pos.x, pos.y)) {
  const free = world.placeFree(pos.x, pos.y)
  if (free) {
    pos.x = free.x
    pos.y = free.y
    console.error(`# adjusted position to ${pos.x},${pos.y}`)
  } else {
    console.error(`# WARNING unwalkable position ${pos.x},${pos.y}`)
  }
}

const save = {
  version: 2,
  starter: 'pimenta',
  party,
  box: [],
  bag: { coconut_ball: 20, golden_ball: 5, potion: 5, super_potion: 2, mango: 2 },
  coins: 4000,
  badges,
  defeated,
  flags: {
    profFirst: true,
    profGift: scenario === 'drbird',
    zephMoved: scenario === 'drbird',
    talks: {}
  },
  seen: Object.fromEntries(Object.keys(data.SPECIES).map(id => [id, true])),
  caught: Object.fromEntries(Object.keys(data.SPECIES).map(id => [id, true])),
  leadIndex: 0,
  position: pos,
  time: 3725,
  champion: false,
  zone: world.zoneAt(pos.x, pos.y),
  savedAt: Date.now()
}

process.stdout.write(JSON.stringify(save))

